from scipy.optimize import least_squares
import warnings; warnings.filterwarnings("ignore")
fams={
 "exp_eT": lambda p: p[0]+p[1]*T+p[2]*T**2+p[3]*np.exp(-p[4]*eps*T**p[5]),
 "sin_eT": lambda p: p[0]+p[1]*T+p[2]*T**2+p[3]*np.cos(p[4]*eps*T**p[5]+p[6]),
 "pow": lambda p: p[0]+p[1]*T**p[2]+p[3]*eps**p[4]*T**p[5],
}
rng=np.random.default_rng(0)
for nm,f in fams.items():
    bc=np.inf; bx=None
    for trial in range(30):
        p0=rng.normal(size=7)
        try:
            r=least_squares(lambda p: np.nan_to_num(f(p)-sigma,nan=1e6,posinf=1e6,neginf=-1e6), p0, max_nfev=500)
            if r.cost<bc: bc=r.cost; bx=r.x
        except Exception as e: pass
    print(nm, 2*bc/300/np.var(sigma), None if bx is None else np.round(bx,3))

